use std::collections::HashMap;impl Solution{pub fn word_pattern(p:String,s:String)->bool{let w:Vec<&str>=s.split_whitespace().collect();if p.len()!=w.len(){return false}let mut a=HashMap::new();let mut b=HashMap::new();for(i,c)in p.chars().enumerate(){if a.get(&c).map(|x|x!=w[i]).unwrap_or(false)||b.get(w[i]).map(|x|*x!=c).unwrap_or(false){return false}a.insert(c,w[i]);b.insert(w[i],c);}true}}
